import { releaseDueHotelGroupBlocks } from '../lib/hotelGroupLifecycle';
import { getContext } from '@keystone-6/core/context';
import type { KeystoneConfig } from '@keystone-6/core/types';
import * as PrismaModule from '@prisma/client';
import { acquireWorkerLease } from '../lib/workerLease';
import { expireHotelHoldBatch } from '../lib/expireHotelHolds';
import { recordWorkerProgress } from '../lib/workerProgress';

export async function runHotelHoldWorkerCycle(
  context: any,
  ownerId: string,
  lease = acquireWorkerLease,
) {
  if (!(await lease(context.prisma, { leaseKey: 'booking-hold-expiry', ownerId, ttlMs: 120_000 }))) return;
  const result = await expireHotelHoldBatch(
    context,
    new Date(),
    () => lease(context.prisma, { leaseKey: 'booking-hold-expiry', ownerId, ttlMs: 120_000 }),
  );
  await releaseDueHotelGroupBlocks(context);
  if (result.failures.length) console.error('Hotel hold expiry records failed:', result.failures.length);
  else if (!result.leaseLost) await recordWorkerProgress(context.prisma, 'holds');
}

export function startHotelHoldJobs(config: KeystoneConfig) {
  if (process.env.NODE_ENV === 'test') return;
  const globalState = globalThis as any; if (globalState.__hotelHoldJobsState) return;
  const context = getContext(config, PrismaModule); const ownerId = `hotel-hold-${process.pid}`; let stopping = false;
  let running = false;
  const run = async () => {
    if (running) return;
    running = true;
    try {
      if (stopping) return;
      await runHotelHoldWorkerCycle(context, ownerId);
    } catch (error) {
      console.error('Hotel hold expiry cycle failed:', error instanceof Error ? error.message : 'unknown error');
    } finally { running = false; }
  };
  const interval=setInterval(()=>void run(),60_000);interval.unref();const shutdown=()=>{stopping=true;clearInterval(interval)};process.once('SIGTERM',shutdown);process.once('SIGINT',shutdown);globalState.__hotelHoldJobsState={interval,shutdown};void run();
}
